    'storyTr' => 'Frederic Edwin Church tarafından 1860 döneminde üretilen "Twilight in the Wilderness", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. In his New York studio, Church painted this spectacular view of a blazing sunset over wilderness near Mount Katahdin in Maine, which he had sketched during a visit nearly two years earlier. Although Church often extolled the grandeur of American landscape in his work, this painting appears to have additional overtones. Created on the eve of the Civil War, the painting\'s subject can be interpreted as symbolically evoking the coming conflagration. Church\'s considerable technica',
