  24 => 
  array (
    'id' => 25,
    'slug' => 'thomas-cole-view-of-schroon-mountain-essex-county-new-york-after-a-storm-25',
    'accessionNumber' => '1917.1335',
    'title' => 'View of Schroon Mountain, Essex County, New York, After a Storm',
    'artist' => 'Thomas Cole',
    'artistBioTr' => 'Thomas Cole — Thomas Cole (American, born England,1801–1848) (American Painting and Sculpture).',
    'artistBioEn' => 'Thomas Cole (American, born England,1801–1848)',
    'category' => 'architecture',
    'year' => 1838,
    'mediumTr' => 'oil on canvas (Cleveland Museum of Art)',
    'mediumEn' => 'oil on canvas',
    'dimensions' => 'Framed: 132.5 x 193.5 x 13 cm (52 3/16 x 76 3/16 x 5 1/8 in.); Unframed: 99.8 x 160.6 cm (39 5/16 x 63 1/4 in.)',
    'resolution' => 'Cleveland Museum of Art CC0 (1263 × 775 px)',
    'storyTr' => 'Thomas Cole tarafından 1838 döneminde üretilen "View of Schroon Mountain, Essex County, New York, After a Storm", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. Championing the American wilderness, Cole declared, "We are still in Eden," in his Essay on American Scenery, published two years before he painted this view of the Adirondacks. The artist sketched the scene in early summer, but when he created the painting in his studio, he rendered it in a dramatic blaze of fall colors. Such a choice likely had nationalistic overtones; he once proclaimed that autumn was "one season where the American forest surpasses all the world in gorgeo',
