    'resolution' => 'Cleveland Museum of Art CC0 (900 × 759 px)',
    'storyTr' => 'Pieter de Hooch tarafından 1663 döneminde üretilen "Portrait of a Family Playing Music", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. The identity of the sitters remains unknown, although the marble floor and mantelpiece, the Transylvanian prayer rug on the table, and the silk clothes all point to the family’s considerable wealth. Furthermore, the richly carved chest at the right supports Chinese vases and Japanese lacquered boxes, a reference to the flourishing Dutch trade with Asia. Music making often took place at home, and its appearance here also signifies the harmoniousness of the family.',
