    'slug' => 'joseph-mallord-william-turner-the-burning-of-the-houses-of-lords-and-commons-16-october-1834-43',
    'accessionNumber' => '1942.647',
    'title' => 'The Burning of the Houses of Lords and Commons, 16 October 1834',
    'artist' => 'Joseph Mallord William Turner',
    'artistBioTr' => 'Joseph Mallord William Turner — Joseph Mallord William Turner (British, 1775–1851) (Modern European Painting and Sculpture).',
    'artistBioEn' => 'Joseph Mallord William Turner (British, 1775–1851)',
    'category' => 'architecture',
    'year' => 1835,
    'mediumTr' => 'oil on canvas (Cleveland Museum of Art)',
    'mediumEn' => 'oil on canvas',
    'dimensions' => 'Framed: 123.5 x 153.5 x 12 cm (48 5/8 x 60 7/16 x 4 3/4 in.); Unframed: 92 x 123.2 cm (36 1/4 x 48 1/2 in.)',
    'resolution' => 'Cleveland Museum of Art CC0 (900 × 668 px)',
    'storyTr' => 'Joseph Mallord William Turner tarafından 1835 döneminde üretilen "The Burning of the Houses of Lords and Commons, 16 October 1834", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. Fire consumed London’s famous Houses of Parliament on the night of October 16, 1834, and people gathered along the banks of the river Thames to gaze in awe at the horrifying spectacle. Initially, a low tide made it difficult to pump water to land and hampered steamers towing firefighting equipment along the river. The blaze burned uncontrollably for hours.J. M. W. Turner records the struggle as the boats in the lower-right corner head toward the flames. Although Turner based ',
