    'resolution' => 'Cleveland Museum of Art CC0 (1179 × 893 px)',
    'storyTr' => 'George Inness tarafından 1892 döneminde üretilen "Sunny Autumn Day", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. Highly prolific, Inness created more than 1,000 works during a career lasting 50 years. Dated just two years before his death, Sunny Autumn Day epitomizes his late style in which the physical landscape is transformed into something akin to a spiritual apparition. Featuring blurred forms and atmospheric effects from translucent colors, this scene reflects Inness’s mystical view of the natural world.',
