    'storyTr' => 'Rembrandt van Rijn tarafından 1635 or earlier döneminde üretilen "Portrait of a Woman", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. At the age of 25, Rembrandt moved from his hometown of Leiden to the bustling city of Amsterdam. Within a few years he had become one of the city’s most successful portrait painters, creating remarkably vivid likenesses that seemed to express the personality and soul of the sitter. Here, Rembrandt used smooth, fluid brushstrokes to recreate the soft texture of the woman’s skin. In contrast, thicker, more textured strokes draw attention to the lavish display of her lace collar',
