  51 => 
  array (
    'id' => 52,
    'slug' => 'william-sidney-mount-the-power-of-music-52',
    'accessionNumber' => '1991.110',
    'title' => 'The Power of Music',
    'artist' => 'William Sidney Mount',
    'artistBioTr' => 'William Sidney Mount — William Sidney Mount (American, 1807–1868) (American Painting and Sculpture).',
    'artistBioEn' => 'William Sidney Mount (American, 1807–1868)',
    'category' => 'digital',
    'year' => 1847,
    'mediumTr' => 'oil on canvas (Cleveland Museum of Art)',
    'mediumEn' => 'oil on canvas',
    'dimensions' => 'Framed: 67 x 78 x 7.5 cm (26 3/8 x 30 11/16 x 2 15/16 in.); Unframed: 43.4 x 53.5 cm (17 1/16 x 21 1/16 in.)',
    'resolution' => 'Cleveland Museum of Art CC0 (1106 × 893 px)',
    'storyTr' => 'William Sidney Mount tarafından 1847 döneminde üretilen "The Power of Music", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. Set in rural Long Island before the Civil War, Mount\'s complex painting presents an African American laborer listening intently to a fiddle tune enjoyed by white men. While a love of music unites the figures in a bond of shared humanity, the two races occupy different spaces--one inside, one outside, both separated by a barn door--effectively symbolizing the pronounced divisions in America at the time.',
    'storyEn' => 'Set in rural Long Island before the Civil War, Mount\'s complex painting presents an African American laborer listening intently to a fiddle tune enjoyed by white men. While a love of music unites the figures in a bond of shared humanity, the two races occupy different spaces--one inside, one outside, both separated by a barn door--effectively symbolizing the pronounced divisions in America at the time.',
    'technicalDetailsTr' => 'oil on canvas · Envanter: 1991.110 · Bölüm: American Painting and Sculpture (CC0 Açık Erişim).',
    'technicalDetailsEn' => 'oil on canvas · Accession: 1991.110 · Department: American Painting and Sculpture (CC0 Open Access).',
