    'resolution' => 'Cleveland Museum of Art CC0 (900 × 554 px)',
    'storyTr' => 'Thomas Cole tarafından 1837 döneminde üretilen "View of Florence", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. Cole visited Italy in 1831 and made a small pencil sketch of this vista of Florence shortly before sunset. In his New York studio six years later, he transformed the drawing into this large oil painting, adding picturesque humans and goats to the foreground. Exhibiting View of Florence alongside a painting of the Catskill Mountains in New York in 1837, Cole set out to prove that he had mastered the very different landscapes of the Old and New Worlds.',
