    'resolution' => 'Cleveland Museum of Art CC0 (739 × 893 px)',
    'storyTr' => 'Albert Bouts tarafından c. 1480 döneminde üretilen "The Annunciation", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. The scene of the Annunciation to Mary that she will give birth to Christ is depicted here as a contemporary scene that may have been familiar to any viewer at the end of the 1400s. Mary is portrayed as an ordinary but wealthy woman who is interrupted by the Archangel Gabriel as she reads a book of hours. This type of book was enormously popular in the late Middle Ages as a prayer and devotional book, particularly among the wealthy, literate nobility, and city aristocracy.',
