    'storyTr' => 'Anne Vallayer-Coster tarafından 1769 döneminde üretilen "Basket of Plums", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. During the later part of the 1700s, fruit still lifes were extremely popular, and a basket of plums was a common motif. In Vallayer\'s painting the details, especially the plums and the basket, emerge from deep shadows. The colors are vivid reds and violets and a sense of immediacy is invoked by the growing moss, the cakes in their crisp papers, and the glass of water with its sparkling highlights and reflections.',
