    'storyTr' => 'Orazio Gentileschi tarafından c. 1623 döneminde üretilen "Danaë", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. Danaë’s father feared a prophecy that his grandson would kill him, so he imprisoned his daughter to protect her from suitors. Yet Jupiter, king of the gods, fell in love with Danaë, and he came to her in the form of gold streaming from the sky. Gentileschi adopted Caravaggio’s method of painting directly from models, pulled to the front of the picture plane, which gives the painting a startling, tangible quality. How',
