  74 => 
  array (
    'id' => 75,
    'slug' => 'washington-allston-samuel-williams-75',
    'accessionNumber' => '1965.474',
    'title' => 'Samuel Williams',
    'artist' => 'Washington Allston',
    'artistBioTr' => 'Washington Allston — Washington Allston (American, 1779–1843) (American Painting and Sculpture).',
    'artistBioEn' => 'Washington Allston (American, 1779–1843)',
    'category' => 'illustration',
    'year' => 1827,
    'mediumTr' => 'oil on canvas (Cleveland Museum of Art)',
    'mediumEn' => 'oil on canvas',
    'dimensions' => 'Framed: 172.5 x 142.5 x 14 cm (67 15/16 x 56 1/8 x 5 1/2 in.); Unframed: 142.2 x 111.8 cm (56 x 44 in.)',
    'resolution' => 'Cleveland Museum of Art CC0 (702 × 893 px)',
    'storyTr' => 'Washington Allston tarafından c. 1817 döneminde üretilen "Samuel Williams", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. Allston’s portrait of his London banker and business agent explores the experience of reverie. Williams looks off absently, perhaps inspired by the pictures in the book he holds. With its view of an Italianate landscape beyond the columns of this invented setting, the painting seemingly invites viewers to join the sitter in dreaming about faraway places.',
