    'storyTr' => 'Gerard ter Borch tarafından c. 1665 döneminde üretilen "Portrait of a Woman", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. Every detail of his subject’s elaborate costume is skillfully recorded: glittering jewels, filmy lace, knots of ribbons, heavy black silk, and shimmering white satin. The ability to recreate satin’s luster was Gerard ter Borch’s particular trademark: he used fine flicks and sweeps of the brush, occasionally adding and wiping away tiny bits of paint to make the white fabric appear to shine. Ter Borch offset the profus',
