    'storyTr' => 'Noël Nicolas Coypel tarafından 1726 döneminde üretilen "The Miracles of Saint James the Greater", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. Noël Nicolas Coypel combined two stories associated with Saint James the Greater, one of the twelve apostles of Christ. In the foreground is the magician Hermogenes, begging forgiveness. Hermogenes had cast a spell on James, but the saint turned the curse back on him. When James offered to protect Hermogenes against the demons assaulting him, the magician cast aside his pagan texts in favor of Christianity. According',
