    'resolution' => 'Cleveland Museum of Art CC0 (1263 × 515 px)',
    'storyTr' => 'Master of the Schlägl Altarpiece tarafından c. 1440s döneminde üretilen "Altarpiece with The Passion of Christ", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. The visual focus of this altarpiece is the suffering and death of Christ on the cross. So-called Passion cycles in art include the events leading up to and following the Crucifixion, not only as single subjects but as scenes meant to be read in sequence. Passion cycles were promoted by the two great teaching orders, the Franciscans and the Dominicans, for whom this subject represented the main religious drama of thei',
