    'id' => 121,
    'slug' => 'paolo-veronese-the-annunciation-121',
    'accessionNumber' => '1950.251',
    'title' => 'The Annunciation',
    'artist' => 'Paolo Veronese',
    'artistBioTr' => 'Paolo Veronese — Paolo Veronese (Italian, 1528–1588) (European Painting and Sculpture).',
    'artistBioEn' => 'Paolo Veronese (Italian, 1528–1588)',
    'category' => 'street',
    'year' => 1585,
    'mediumTr' => 'oil on canvas (Cleveland Museum of Art)',
    'mediumEn' => 'oil on canvas',
    'dimensions' => 'Framed: 176 x 159.5 x 9.5 cm (69 5/16 x 62 13/16 x 3 3/4 in.); Unframed: 150 x 133.4 cm (59 1/16 x 52 1/2 in.)',
    'resolution' => 'Cleveland Museum of Art CC0 (810 × 900 px)',
    'storyTr' => 'Paolo Veronese tarafından c. 1580 döneminde üretilen "The Annunciation", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. Although Veronese is best known for his large-scale, pageant-like presentations, here the artist has taken the narrative of the Annunciation (the announcement of the angel Gabriel to the Virgin Mary that she would conceive and bear a son) and compressed the figures close to one another, creating a startling intimacy. According to a tradition established by the medieval writer Saint Bernard, Mary has been reading from',
    'storyEn' => 'Although Veronese is best known for his large-scale, pageant-like presentations, here the artist has taken the narrative of the Annunciation (the announcement of the angel Gabriel to the Virgin Mary that she would conceive and bear a son) and compressed the figures close to one another, creating a startling intimacy. According to a tradition established by the medieval writer Saint Bernard, Mary has been reading from',
