    'resolution' => 'Cleveland Museum of Art CC0 (900 × 21 px)',
    'storyTr' => 'Japan, Kamakura period (1185–1333) tarafından early 1300s döneminde üretilen "The Illustrated Miraculous Origins of the Yūzū Nenbutsu School", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. This painting is the second of a set of two illustrated handscrolls. The first scroll depicts the biography of the Japanese Buddhist monk Ryōnin. This scroll begins with scenes of Ryōnin’s death and relates episodes illustrating the efficacy of following his teachings. Ryōnin asserted the total interconnectedness of all things and the spiritual benefit of chanting the name of the Buddha Amida for one another.',
