    'resolution' => 'Cleveland Museum of Art CC0 (668 × 893 px)',
    'storyTr' => 'Rembrandt van Rijn tarafından c. 1629 or 1632 döneminde üretilen "A Young Man with a Chain", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. This painting is an example of a tronie, a Dutch word meaning “head” or “facial expression.” Tronies were not intended to be identifiable portraits, but artistic investigations of facial appearance and fanciful costume. Particularly in the years around 1630, Rembrandt used this popular format to explore different lighting effects and facial expressions. Here, the strong contrast of light and shade shapes the contours',
