    'storyTr' => 'Japan, Kamakura period (1185–1333) tarafından 1200s döneminde üretilen "The White Path Between Two Rivers", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. This painting is a visual presentation of a teaching ascribed to the Chinese Buddhist monk Shandao (善導) (613–681). It describes a challenging journey to the land of the Buddha Amida along a narrow path between a river of fire and a river of water. The story is about escaping the six paths of reincarnation—the heavens and hells, as well as the realms of humans, animals, hungry ghosts, and fierce beings. The Buddha Ami',
