    'storyTr' => 'Korea, Joseon dynasty (1392–1910) tarafından late 1800s döneminde üretilen "Tiger Family", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. In deep mountains, a tigress, two cubs, and a leopard welcome the early morning sun. This is not merely a playful scene but a well calculated image with symbols of longevity (pine trees), prosperity (tigress and cubs), and good fortune (leopard). Traditionally, on New Year’s Eve, the image of a fearsome-looking tiger was pasted on entrance doors to ward off evil spirits. Conventional Korean tiger paintings often incl',
