    'storyTr' => 'Édouard Manet tarafından c. 1871–72 döneminde üretilen "Berthe Morisot with a Muff", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. This is one of two portraits Manet painted of Morisot dressed for winter in a heavy coat and feathered hat. (See Berthe Morisot with a Half Veil, also in this gallery.) Manet’s wide brushstrokes and crosshatchings, which describe areas of shadow, evoke the sketchy quality of Morisot’s own paintings, likely Manet’s nod to his subject’s identity as an artist.',
