    'storyTr' => 'Ernest Meissonier tarafından 1855 döneminde üretilen "A Painter", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. Meissonier often depicted artists and musicians of the 1600s and 1700s engaged in their work. This artist is busy painting a small canvas depicting a nymph and satyr. The artist’s 18th-century costume—nearly 100 years out of date at the time of the painting’s creation—transforms the scene into a charming historical fiction. Meissonier exhibited the painting at the Paris Salon of 1857.',
