  170 => 
  array (
    'id' => 171,
    'slug' => 'carolino-da-viterbo-virgin-and-child-with-saint-jerome-and-saint-catherine-of-al-171',
    'accessionNumber' => '1956.719',
    'title' => 'Virgin and Child with Saint Jerome and Saint Catherine of Alexandria',
    'artist' => 'Carolino da Viterbo',
    'artistBioTr' => 'Carolino da Viterbo — Carolino da Viterbo (Italian) (Medieval Art).',
    'artistBioEn' => 'Carolino da Viterbo (Italian)',
    'category' => 'concept',
    'year' => 1455,
    'mediumTr' => 'tempera and gold on wood panel (Cleveland Museum of Art)',
    'mediumEn' => 'tempera and gold on wood panel',
    'dimensions' => 'Framed: 68.5 x 47.5 x 5 cm (26 15/16 x 18 11/16 x 1 15/16 in.); Unframed: 59.7 x 39 cm (23 1/2 x 15 3/8 in.)',
    'resolution' => 'Cleveland Museum of Art CC0 (621 × 893 px)',
    'storyTr' => 'Carolino da Viterbo tarafından c. 1450 döneminde üretilen "Virgin and Child with Saint Jerome and Saint Catherine of Alexandria", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. In his right hand, the Christ child grasps a stem of roses. The beauty and fragrance of roses symbolize heaven, while their thorny stems allude to the crown of thorns and Christ\'s suffering. The bird he holds in his left hand symbolizes the human soul. The elaborate haloes with Latin inscriptions identify the figures and help organize the composition. The names of Christ, Saint Jerome, and Saint Catherine of Alexandr',
    'storyEn' => 'In his right hand, the Christ child grasps a stem of roses. The beauty and fragrance of roses symbolize heaven, while their thorny stems allude to the crown of thorns and Christ\'s suffering. The bird he holds in his left hand symbolizes the human soul. The elaborate haloes with Latin inscriptions identify the figures and help organize the composition. The names of Christ, Saint Jerome, and Saint Catherine of Alexandr',
