    'resolution' => 'Cleveland Museum of Art CC0 (623 × 893 px)',
    'storyTr' => 'James Tissot tarafından 1878 döneminde üretilen "Seaside (July: Specimen of a Portrait)", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. This painting depicts a woman reclining upon an upholstered couch on a summer day while light filters through a partially closed awning that provides a glimpse of a beach in the background. James Tissot’s mature works from this time were more likely to convey a mood—here of a languid summer afternoon—than a specific narrative. The model for this painting was Kathleen Newton, born Kathleen Ashburnham Kelly (1854–1882)',
