    'storyTr' => 'Jean Bernard Restout tarafından c. 1771 döneminde üretilen "Sleep", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. The tradition of painting nude male figures in a studio setting was the cornerstone of artistic practice, teaching artists to depict the human body in complex poses in order to create larger narratives. However, by the late 1700s, some artists began to see these studies as independent works of art. By adding the wings and the poppies, Restout transformed his study into a more specific subject, and he first exhibited ',
