    'storyTr' => 'Hendrik van Balen tarafından c. 1620 döneminde üretilen "The Trinity", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. This vividly colored altarpiece was made in Antwerp, the center of religious learning in Catholic Flanders. In the mid-1500s when the Catholic Church mounted a defense against the spread of Protestant reforms, known as the Counter-Reformation, it encouraged the production of religious images that promoted Catholic doctrine, offering opportunities for artists like Rubens, Van Dyck, and Van Balen. Van Balen’s painting ',
