    'storyTr' => 'Matsumura Goshun tarafından 1785 döneminde üretilen "Seventy-Two Peaks Under the Blue Sky with Mount Furong", The Cleveland Museum of Art Açık Erişim (CC0) koleksiyonunda yer alan orijinal bir başyapıttır. The low height of this folding screen suggests its use as a partition in a small tearoom. An inscription identifies the scene as the 72-peak Heng mountain range in Hunan, China, associated with Buddhist and Daoist traditions and celebrated in poetry. Special mention in the inscription is made of Mount Furong, one of the peaks in the range. Matsumura Goshun may have drawn inspiration from his teacher, Yosa Buson (与謝蕪村',
    'storyEn' => 'The low height of this folding screen suggests its use as a partition in a small tearoom. An inscription identifies the scene as the 72-peak Heng mountain range in Hunan, China, associated with Buddhist and Daoist traditions and celebrated in poetry. Special mention in the inscription is made of Mount Furong, one of the peaks in the range. Matsumura Goshun may have drawn inspiration from his teacher, Yosa Buson (与謝蕪村',
